-- INSERT IGNORE throughout: a world that still has his rows keeps them untouched, a new world gets these.
-- Chol'aruk the Ravener, rebuilt from what we hold ourselves: our saved Wowhead Forever quest page (texts, rewards, level, giver) and our own
-- Razormane Pathfinder (3456) as the base of his template (faction, flags), with the stats of a level 20 elite. The model is the
-- Pathfinder's, scaled up: PLACEHOLDER until we hold his real model. He stands on the cave floor under Thorn Hill (the spot of the owner's
-- GM check). Quest 97005 (Alliance, Bainham, level 21, needs 15): kill him, bring his head (item 276070); choice of four rewards.
SELECT 267307 AS `entry`, `KillCredit1`, `KillCredit2`, 'Chol''aruk' AS `name`, `femaleName`, 'The Ravener' AS `subname`, `TitleAlt`, `IconName`, `RequiredExpansion`, `VignetteID`, `faction`, 0 AS `npcflag`, `speed_walk`, `speed_run`, 1 AS `scale`, 1 AS `Classification`, `dmgschool`, `BaseAttackTime`, `RangeAttackTime`, `BaseVariance`, `RangeVariance`, `unit_class`, `unit_flags`, `unit_flags2`, `unit_flags3`, `family`, `trainer_class`, `type`, `VehicleId`, '' AS `AIName`, 1 AS `MovementType`, `ExperienceModifier`, `RacialLeader`, `movementId`, `WidgetSetID`, `WidgetSetUnitConditionID`, `RegenHealth`, `CreatureImmunitiesId`, `flags_extra`, '' AS `ScriptName`, NULL AS `StringId`, 0 AS `VerifiedBuild` FROM `creature_template` WHERE `entry`=3456;
SELECT 267307 AS `Entry`, `DifficultyID`, `LevelScalingDeltaMin`, `LevelScalingDeltaMax`, `ContentTuningID`, `HealthScalingExpansion`, 4 AS `HealthModifier`, `ManaModifier`, `ArmorModifier`, 1.5 AS `DamageModifier`, 0 AS `CreatureDifficultyID`, `TypeFlags`, `TypeFlags2`, `TypeFlags3`, 267307 AS `LootID`, 0 AS `PickPocketLootID`, 0 AS `SkinLootID`, 60 AS `GoldMin`, 120 AS `GoldMax`, `StaticFlags1`, `StaticFlags2`, `StaticFlags3`, `StaticFlags4`, `StaticFlags5`, `StaticFlags6`, `StaticFlags7`, `StaticFlags8`, 0 AS `VerifiedBuild` FROM `creature_template_difficulty` WHERE `Entry`=3456 AND `DifficultyID`=0;
SELECT 267307, 0, `CreatureDisplayID`, 2.2, 1, 0 FROM `creature_template_model` WHERE `CreatureID`=3456 AND `Idx`=0;
SELECT 267307,0,276070,100,1,1,0,1,1,'Chol''aruk - Chol''aruk''s Head (quest 97005)' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `creature_loot_template` WHERE `Entry`=267307 AND `Item`=276070);

-- 97005 Chol'aruk the Ravener (level 21, required 15) -- Wowhead Forever page
UPDATE `creature_template` SET `npcflag`=`npcflag`|2 WHERE `entry` IN (267309);
