INSERT IGNORE INTO `quest_template` (`ID`,`QuestType`,`QuestSortID`,`RewardXPDifficulty`,`RewardXPMultiplier`,`RewardMoneyMultiplier`,`RewardSpell`,`StartItem`,`Flags`,`AllowableRaces`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog`,`RewardChoiceItemID1`,`RewardChoiceItemQuantity1`,`RewardChoiceItemID2`,`RewardChoiceItemQuantity2`,`RewardChoiceItemID3`,`RewardChoiceItemQuantity3`,`RewardChoiceItemID4`,`RewardChoiceItemQuantity4`,`RewardFactionID1`,`RewardFactionOverride1`) VALUES (97005,2,17,5,1,1,0,0,8,4294967373,'Chol''aruk the Ravener','Gather strong allies and find the lair of Chol''aruk. Kill the abomination and bring me its head.','There are rumors of a colossal abomination that makes its lair at a cave to the northwest of here, on the plateau known as Thorn Hill. The Razormane call it Chol''aruk or "The Ravener" and those that have seen it say it''s so massive that it can swallow an orc whole.$B$BFew believe such tales, but I do... because I''ve fought one like it myself. On the honor of those I lost to these things, this beast must die.','','',276886,1,276887,1,276888,1,276889,1,72,15000);
