INSERT IGNORE INTO `quest_request_items` (`ID`,`CompletionText`,`VerifiedBuild`) VALUES (97005,'It took six of us to defeat one of these creatures, and it still managed to kill all but myself and one other before we were able to bring it down.$B$BThis far from alliance lands I should leave it well enough alone. Light knows I''ll lose little sleep over a few tauren savages or orcish brutes. However, the honor of my fallen brothers demands action.',0);
INSERT IGNORE INTO `quest_offer_reward` (`ID`,`RewardText`,`VerifiedBuild`) VALUES (97005,'My dead men will rest easier knowing that there is one less of these monsters in the world. You''ve done well, and are a true and stalwart defender of the Alliance. Thank you.$B$BGo with honor, $n.',0);
